// フォームの日本語ラベルを pc-register の入力形式に変換するだけ。
// 検証・重複チェック・NetBox 登録・タスク起票は pc-register 側が行う
// (Webhook から直接呼ぶ経路と処理を共通にするため)。
// 設計: docs/design/02-pc-register.md

const f = $input.first()?.json ?? {};
const get = (k) => (f[k] ?? '').toString().trim();
const PURPOSE = { '開発': 'dev', '検証': 'test', 'その他': 'misc' };

return [{ json: {
  acquisition: get('登録区分') === '他部署からの搬入' ? 'transfer' : 'purchase',
  user_name: get('利用者名'),
  user_email: get('利用者のメールアドレス'),
  model: get('機種・モデル'),
  acquired_at: get('取得日'),
  purpose: PURPOSE[get('用途')] ?? 'dev',
  asset_no: get('資産管理番号'),
  asset_no_provisional: get('資産管理番号は仮の値').startsWith('はい'),
  computer_name: get('コンピュータ名'),
  computer_name_provisional: get('コンピュータ名は仮の値').startsWith('はい'),
  ip: get('IP アドレス') || null,
  installed: get('導入済みの必須ソフト').split(',').map((s) => s.trim()).filter(Boolean),
}}];

// 完了画面に出す文面を作る。何が起きたかと、次に誰が何をするかを書く。
const r = $input.first()?.json ?? {};
const lines = [
  `NetBox に登録しました(資産管理番号 ${r.asset_no} / ${r.computer_name})。`,
];
if (r.ip) lines.push(`IP アドレス ${r.ip} を割り当てました。`);
if ((r.tasks ?? []).length) {
  lines.push('', '担当者に次の依頼を送りました:');
  for (const t of r.tasks) lines.push(`・${t}`);
  lines.push('', '完了までリマインドが届きます。');
} else {
  lines.push('', '追加の作業はありません。');
}
lines.push('', `NetBox: ${r.netbox_url}`);
return [{ json: { message: lines.join('\n') } }];
